//! # Superquadric particles against LIGGGHTS-PUBLIC 3d5c00f2 (gh:#1415)
//!
//! **Methodology.** The decks `reference-data/liggghts/in.sq_drop` and
//! `in.sq_collide` (generated by `make_superquadric_decks.sh`) were run with an
//! upstream `lmp_serial` built with `-DSUPERQUADRIC_ACTIVE_FLAG
//! -DNONSPHERICAL_ACTIVE_FLAG` (recipe in `upstream_source/README.md`), and
//! their `%.17g` frame dumps of `x v omega quat` converted with `sq2csv.sh` to
//! `sq_drop.csv` and `sq_collide.csv`. The same set-up runs here through
//! [`SuperquadricSystem`]; every value of every particle at every frame is
//! compared on its IEEE-754 bit pattern.
//!
//! * `sq_drop`: one cube-like superquadric (`n1 = n2 = 6`, half-axes 4, 3,
//!   2.5 mm, density 2500, `quat_direct 0.9 0.3 0.2 0.1`), `v = (0.1, 0,
//!   -0.5)`, `omega = (3, -2, 5)`, falls under gravity onto a `zplane` wall
//!   (Hertz + history, `E = 1e7`, `nu = 0.3`, `e = 0.5`, `mu = 0.4`,
//!   `dt = 1e-5`); 10 frames to step 10 000.
//! * `sq_collide`: that blob and an `n1 = 4, n2 = 3` blob (half-axes 3.5, 3,
//!   4 mm, density 1500, `quat_direct 0.7 -0.2 0.5 0.4`) meet obliquely with
//!   spin, no gravity, no walls; 10 frames to step 3 000.
//!
//! **Pass criterion.** The counts of bit-identical values below, pinned
//! (gh:#1455), and every other value within `1e-8` relative.
//!
//! **Results** (2026-11-13, Rust 1.99.1, PETIR `RealMath`):
//!
//! | deck | bit-identical | first differing frame | worst relative difference |
//! |---|---|---|---|
//! | `sq_drop` | **36 / 130** (frames 1, 500 and 10 more values) | step 1000 (first wall contact at step 734) | `3.50e-12` |
//! | `sq_collide` | **116 / 260** (frames 1, 200, 400 and 38 more values) | step 600 (first contact between 400 and 600) | `2.39e-10` |
//!
//! **The residue is the maths library, proved by a swap.** With the six
//! transcendental calls of `superquadric.rs` routed to glibc instead
//! (`pow`, `sin`, `cos`, `exp`, `lgamma` by `extern "C"`, and `cbrt` as
//! glibc's `cbrtf64` alias, because Rust's std `cbrt` resolves to
//! compiler-builtins' libm, not glibc), both decks are **130 / 130 and
//! 260 / 260 bit-identical**. With glibc for every call except `cbrt`, the
//! counts are the PETIR counts above, so the whole residue enters through
//! `cbrt` in the volume-equivalent radius `cbrt(3V / 4 pi)`, which the wall
//! and pair Hertz radius use: libm returns `3.72342409315634237e-3` where
//! glibc returns `3.72342409315634280e-3` (1 ulp) for this blob. The wall
//! torque then differs in the last bit at the first contact step (734) and
//! the difference grows through the contact. Pinned per the gh:#1455
//! decision (keep PETIR's maths).

use outram_park_fork_liggghts::granular::MaterialTable;
use outram_park_fork_liggghts::particle::Vec3;
use outram_park_fork_liggghts::superquadric::{
    SuperquadricParticle, SuperquadricPlaneWall, SuperquadricSystem,
};
use uom::si::f64::{Length, MassDensity, Time};
use uom::si::{length::meter, mass_density::kilogram_per_cubic_meter, time::second};

/// Bit-identical values of `sq_drop` (of 10 frames x 13 values).
const DROP_BIT_IDENTICAL: usize = 36;
/// Bit-identical values of `sq_collide` (of 10 frames x 2 particles x 13 values).
const COLLIDE_BIT_IDENTICAL: usize = 116;

fn read(name: &str) -> Option<String> {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../reference-data/liggghts")
        .join(name);
    std::fs::read_to_string(path).ok()
}

fn m(v: f64) -> Length {
    Length::new::<meter>(v)
}

fn rho(v: f64) -> MassDensity {
    MassDensity::new::<kilogram_per_cubic_meter>(v)
}

fn materials() -> MaterialTable {
    MaterialTable::new(&[(1.0e7, 0.3)], &[&[0.5]], &[&[0.4]]).unwrap()
}

fn blob1(x: [f64; 3], v: Vec3, omega: Vec3) -> SuperquadricParticle {
    SuperquadricParticle::new(
        [m(x[0]), m(x[1]), m(x[2])],
        [m(0.004), m(0.003), m(0.0025)],
        [6.0, 6.0],
        rho(2500.0),
        [0.9, 0.3, 0.2, 0.1],
        v,
        omega,
        0,
    )
    .unwrap()
}

/// Rows `step -> [id, 13 values]` of a reference CSV.
fn reference(text: &str) -> Vec<(u64, Vec<f64>)> {
    text.lines()
        .skip(1)
        .map(|l| {
            let f: Vec<&str> = l.split(',').collect();
            let step: u64 = f[0].parse().unwrap();
            let vals: Vec<f64> = f[2..].iter().map(|s| s.parse().unwrap()).collect();
            (step, vals)
        })
        .collect()
}

fn values(p: &SuperquadricParticle) -> [f64; 13] {
    [
        p.x.x, p.x.y, p.x.z, p.v.x, p.v.y, p.v.z, p.omega.x, p.omega.y, p.omega.z, p.quat[0],
        p.quat[1], p.quat[2], p.quat[3],
    ]
}

/// Run `sys` through the reference frames; returns (bit-identical, total,
/// worst relative difference).
fn compare(
    mut sys: SuperquadricSystem,
    refs: &[(u64, Vec<f64>)],
    np: usize,
) -> (usize, usize, f64) {
    let mut same = 0;
    let mut total = 0;
    let mut worst: f64 = 0.0;
    for (k, chunk) in refs.chunks(np).enumerate() {
        let step = chunk[0].0;
        sys.run(step - sys.step_count());
        for (ip, (_, want)) in chunk.iter().enumerate() {
            let got = values(&sys.particles()[ip]);
            for c in 0..13 {
                total += 1;
                if got[c].to_bits() == want[c].to_bits() {
                    same += 1;
                } else {
                    let rel = (got[c] - want[c]).abs() / want[c].abs().max(1e-300);
                    worst = worst.max(rel);
                    if k < 3 {
                        eprintln!(
                            "step {step} atom {ip} col {c}: {:e} vs {:e}",
                            got[c], want[c]
                        );
                    }
                }
            }
        }
    }
    (same, total, worst)
}

#[test]
fn sq_drop_against_liggghts() {
    let Some(text) = read("sq_drop.csv") else {
        eprintln!("sq_drop.csv not found; skipping");
        return;
    };
    let refs = reference(&text);
    let p = blob1(
        [0.0, 0.0, 0.008],
        Vec3::new(0.1, 0.0, -0.5),
        Vec3::new(3.0, -2.0, 5.0),
    );
    let sys = SuperquadricSystem::new(vec![p], materials(), Time::new::<second>(1e-5))
        .unwrap()
        .with_plane_wall(SuperquadricPlaneWall {
            dim: 2,
            coord: 0.0,
            wall_type: 0,
        })
        .unwrap()
        .with_gravity(9.81, Vec3::new(0.0, 0.0, -1.0))
        .unwrap();
    let (same, total, worst) = compare(sys, &refs, 1);
    eprintln!("sq_drop: {same}/{total} bit-identical, worst relative difference {worst:e}");
    assert_eq!(total, 130);
    assert_eq!(same, DROP_BIT_IDENTICAL);
    assert!(worst < 1e-8, "{worst:e}");
}

#[test]
fn sq_collide_against_liggghts() {
    let Some(text) = read("sq_collide.csv") else {
        eprintln!("sq_collide.csv not found; skipping");
        return;
    };
    let refs = reference(&text);
    let a = blob1(
        [-0.006, 0.0, 0.05],
        Vec3::new(0.4, 0.0, 0.0),
        Vec3::new(0.0, 4.0, 0.0),
    );
    let b = SuperquadricParticle::new(
        [m(0.006), m(0.0015), m(0.051)],
        [m(0.0035), m(0.003), m(0.004)],
        [4.0, 3.0],
        rho(1500.0),
        [0.7, -0.2, 0.5, 0.4],
        Vec3::new(-0.4, 0.0, 0.0),
        Vec3::new(2.0, 0.0, -3.0),
        0,
    )
    .unwrap();
    let sys = SuperquadricSystem::new(vec![a, b], materials(), Time::new::<second>(1e-5)).unwrap();
    let (same, total, worst) = compare(sys, &refs, 2);
    eprintln!("sq_collide: {same}/{total} bit-identical, worst relative difference {worst:e}");
    assert_eq!(total, 260);
    assert_eq!(same, COLLIDE_BIT_IDENTICAL);
    assert!(worst < 1e-8, "{worst:e}");
}
